# Real-Time Example: Streaming 20GB S3 Log File without OOM Crash
import json

def stream_s3_log_file(file_path):
    """Generates one parsed JSON record at a time"""
    with open(file_path, 'r', encoding='utf-8') as file:
        for line_num, line in enumerate(file, 1):
            if line.strip():
                yield json.loads(line) # Yields 1 line at a time

# Production Pipeline Usage
log_stream = stream_s3_log_file('large_server_logs.json')
for record in log_stream:
    # Process record line by line (RAM stays below 50MB!)
    if record.get('status') == 500:
        print(f"Alert: Server Error on IP {record.get('ip')}")
